import React, { useEffect, useState } from "react";
import Navbar from "../components/Navbar";
import { doctorAPI } from "../services/api";

export default function DoctorsPage() {
  const [doctors, setDoctors] = useState([]);
  const [specializations, setSpecializations] = useState([]);
  const [filters, setFilters] = useState({ availability: "all", specialization: "" });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const load = () => {
    setLoading(true);
    doctorAPI.list(filters)
      .then(({ data }) => { setDoctors(data.doctors); setSpecializations(data.specializations); })
      .catch(() => setError("Failed to load doctors"))
      .finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, [filters]);

  return (
    <div className="page">
      <Navbar />
      <main className="container main-content">
        <h1 style={{ fontSize: "1.5rem", fontWeight: 700, marginBottom: "1.5rem" }}>Doctors Directory</h1>

        {/* Filters */}
        <div className="card" style={{ marginBottom: "1.5rem" }}>
          <div style={{ display: "flex", gap: "1rem", flexWrap: "wrap", alignItems: "flex-end" }}>
            <div className="form-group" style={{ marginBottom: 0 }}>
              <label>Availability</label>
              <select className="form-control" value={filters.availability} onChange={e => setFilters({ ...filters, availability: e.target.value })}>
                <option value="all">All</option>
                <option value="online">Online</option>
                <option value="offline">Offline</option>
              </select>
            </div>
            <div className="form-group" style={{ marginBottom: 0, minWidth: 200 }}>
              <label>Specialization</label>
              <select className="form-control" value={filters.specialization} onChange={e => setFilters({ ...filters, specialization: e.target.value })}>
                <option value="">All specializations</option>
                {specializations.map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
          </div>
        </div>

        {error && <div className="alert alert-error">{error}</div>}

        {loading ? <div className="loading-screen"><span className="spinner"></span></div> : (
          <div className="grid-3">
            {doctors.length === 0 ? (
              <p style={{ color: "var(--text-muted)", gridColumn: "1/-1" }}>No doctors found.</p>
            ) : doctors.map((d) => (
              <div key={d._id} className="card">
                <div className="doctor-card">
                  <div className="doctor-avatar">{d.name[0].toUpperCase()}</div>
                  <div className="doctor-info">
                    <h4>Dr. {d.name}</h4>
                    <p className="doctor-meta">{d.specialization || "General Physician"}</p>
                    <span className={`badge ${d.isAvailable ? "badge-success" : "badge-warning"}`}>
                      {d.isAvailable ? "● Online" : "○ Offline"}
                    </span>
                    {d.availableFrom && d.availableTo && (
                      <p className="doctor-meta" style={{ marginTop: ".3rem" }}>{d.availableFrom} – {d.availableTo}</p>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
}
